import { useState } from "react";

export default function FeedbackForm({ order }) {
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState("");

  const submitFeedback = async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/api/feedback/submit/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          order_id: order.order_id,
          user: order.user,   // ✅ FIX HERE
          rating: Number(rating),
          comment
        })
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.error || "Submission failed");
      } else {
        setSubmitted(true);
      }

    } catch (err) {
      setError("Server not reachable");
    }
  };

  if (submitted) {
    return <p style={{ color: "green" }}>Feedback submitted ✔</p>;
  }

  return (
    <div className="feedback-box">
      <h4>Give Feedback</h4>

      {error && <p style={{ color: "red" }}>{error}</p>}

      <select value={rating} onChange={e => setRating(e.target.value)}>
        {[5, 4, 3, 2, 1].map(v => (
          <option key={v} value={v}>{v} Stars</option>
        ))}
      </select>

      <textarea
        placeholder="Comment (optional)"
        value={comment}
        onChange={e => setComment(e.target.value)}
      />

      <button onClick={submitFeedback}>Submit</button>
    </div>
  );
}
